def readout_name(block: nn.Module, source_readout: str) -> str:
    """The one Linear in this block whose name fullmatches the readout regex.

    A regex, not a literal name, because Qwen3.5 is hybrid: `self_attn.o_proj` exists on the
    8 full-attention blocks and `linear_attn.out_proj` on the other 24, so no single name
    covers every layer. Same matching rule as steering_lite.target.find_targets, which picks
    the apply-time hooks.
    """
    hits = [name for name, mod in block.named_modules()
            if name and re.fullmatch(source_readout, name) and isinstance(mod, nn.Linear)]
