@contextmanager
def _activation_source_recorder(
    blocks: nn.ModuleList,
    source_layers: tuple[int, ...],
    target_layer: int,
    source_readout: str | None,
    *,
    start_graph_at: int | None = None,
    record_input: bool = False,
):
    """Record residual block outputs, but read `source_readout` at source layers.

    `source_readout is None` records the block output (residual) everywhere, exactly
    like `jlens.ActivationRecorder`. When set (a regex, e.g. `"mlp.up_proj"`), source
    layers record that submodule instead, so the pullback source vectors live in the
    submodule's space (e.g. the MLP intermediate, d=3.6x d_model) while the target
    cotangent stays on the residual. This is the `vjp_delta`-as-read-into-activation-
    readout variant.

    `record_input` reads the submodule's INPUT rather than its output, the pre-write
    space of a residual writer. Pair it with apply_mode="pre_write", which pushes the
    offset through the same weight, because a forward hook cannot change an input.

    Yields {key: tensor} where key is the layer index. Source keys hold the
    submodule tensor; target key holds the residual block output.
    """
    activations: dict[int, Tensor] = {}
    handles = []

    def make_hook(index: int, is_graph_root: bool):
        def hook(_module: nn.Module, _inputs, output) -> None:
            tensor = output if torch.is_tensor(output) else output[0]
            if is_graph_root:
                tensor.requires_grad_(True)
            activations[index] = tensor

        return hook

    def make_pre_hook(index: int, is_graph_root: bool):
        # A forward hook fires after the module has consumed its input, too late to start a
        # graph there, so the input side needs a pre-hook.
        def pre_hook(_module: nn.Module, inputs) -> None:
            tensor = inputs[0]
            if is_graph_root:
                tensor.requires_grad_(True)
            activations[index] = tensor

        return pre_hook

    for index in sorted(set(source_layers) | {target_layer} | ({} if start_graph_at is None else {start_graph_at})):
        is_source_readout = index in source_layers and source_readout is not None
        if is_source_readout:
            module = blocks[index].get_submodule(readout_name(blocks[index], source_readout))
        else:
            module = blocks[index]
        is_root = index == start_graph_at
        if record_input and is_source_readout:
            handles.append(module.register_forward_pre_hook(make_pre_hook(index, is_root)))
        else:
            handles.append(module.register_forward_hook(make_hook(index, is_root)))
    try:
        yield activations
    finally:
        for handle in handles:
            handle.remove()


